var opponentReportKey=null,opponentMatchContext=null;
function renderOpponentReport(){
 const host=document.getElementById('opposition-report');if(!host||host.hidden||view!=='match'||!state)return;
 const key=[state.seed,state.minute,state.tactic,state.lineup.map(id=>id+':'+state.players[id].energy).join(',')].join('|');if(key===opponentReportKey)return;
 const d=Opposition.read(season);if(!d.valid){host.innerHTML='';return;}opponentReportKey=key;
 const text=matchdayText,n=n=>Math.round(n),plan=typeof TacticsBoard!=='undefined'?TacticsBoard.read(season):null,keyPlayer=d.keyPlayer,keyRow=keyPlayer&&d.lineup.find(p=>p.id===keyPlayer.id);
 const keyPlayerMarkup=keyPlayer?'<article class="opposition-key-player" aria-label="요주의 선수 '+text(keyPlayer.name)+'"><div class="opposition-key-marker" aria-hidden="true"><span>'+text(keyRow?.no||'★')+'</span><small>KEY</small></div><div class="opposition-key-copy"><div><span>요주의 선수</span><b>'+text(keyPlayer.role)+'</b></div><h3>'+text(keyPlayer.name)+'</h3><p>'+text(keyPlayer.pos)+' · '+text(keyPlayer.threat)+'</p></div><span class="opposition-key-focus">상대 전술의 중심</span></article>':'';
 host.innerHTML='<section class="opposition-card"><header><div><span class="eyebrow">OPPOSITION / '+(state.phase==='prep'?'킥오프 전':'경기 중')+'</span><h2>'+text(d.club.name)+'</h2><p>'+text(d.plan.description)+'</p></div><span class="opposition-crest" style="background:'+d.club.color+'">'+text(d.club.code)+'</span></header><div class="opposition-plan"><span>포메이션 <b>'+d.plan.formation.split('').join('–')+'</b></span><span>전술 성향 <b>'+text(d.plan.label)+'</b></span><span>리그 최근 경기 <b>'+text(d.recent.join(' · ')||'기록 없음')+'</b></span></div>'+keyPlayerMarkup+'<div class="opposition-condition"><span>상대 체력 <b>'+n(d.condition.opponent)+'</b></span><span>활동 인원 <b>'+d.activePlayers.ours+' : '+d.activePlayers.opponent+'</b></span><span>우리 활동 선수 <b>'+n(d.condition.ours)+'</b></span><span>체력 주의 <b>'+d.condition.tired+'명</b></span></div><div class="opposition-comparisons">'+d.comparisons.map(r=>'<div><span>'+r.label+'</span><b>'+n(r.ours)+' <i>:</i> '+n(r.opponent)+'</b><small>우리 / 상대</small></div>').join('')+'</div><p class="opposition-advice">'+text(d.advice)+(plan?.valid?' <strong>코치 제안: '+text(plan.recommendation.label)+'</strong>':'')+'</p><div class="opposition-roster-heading"><h3>'+(state.phase==='prep'?'상대 예상 선발':'상대 선발')+' 11명</h3><span>능력 100점 · 체력은 경기 중 감소</span></div><table class="opposition-roster"><thead><tr><th>선수 / 포지션</th><th>주능력</th><th>속도</th><th>지구력</th><th>체력</th></tr></thead><tbody>'+d.lineup.map(p=>{const featured=keyPlayer?.id===p.id,classes=[p.dismissed?'opposition-dismissed':'',featured?'opposition-key-row':''].filter(Boolean).join(' ');return '<tr'+(classes?' class="'+classes+'"':'')+'><td><i>'+p.no+'</i><span class="opposition-player-name">'+text(p.name)+(featured?'<em class="opposition-key-badge">요주의</em>':'')+'<small>'+p.pos+' · '+p.primaryLabel+'</small></span></td><td>'+p.primary+'</td><td>'+p.speed+'</td><td>'+p.endurance+'</td><td><b>'+n(p.energy)+'</b><small>'+(p.dismissed?'퇴장':p.condition)+'</small></td></tr>';}).join('')+'</tbody></table><p class="opposition-note">'+(season.suspensions?'우리 구단은 대회별 경고 3회·퇴장 시 출전 정지를 적용합니다. 상대 선수 카드는 이번 경기 안에서만 적용합니다.':'기존 규칙: 카드는 이번 경기 안에서만 적용합니다. 홈에서 누적 출전 정지 규칙을 켤 수 있습니다.')+' 주능력: 선방·수비·패스·결정력. 전력 비교는 현재 체력을 반영합니다. 위의 빠른 전술로 지시를 바꾸거나 전술 분석에서 비교하세요.</p></section>';
}
